window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-18491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠκρόαμαι, ἠκροασάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 169 na letra η · nº geral 18491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀκροάομαι.</p></section></article>\n<article id=\"entry-dgp-18492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥκω</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra η · nº geral 18492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἧκον, fut. ἥξω, aor. ἧξα, perf. ἧκα, m.-q.-perf. ἥκειν) 1 (pessoa) ter vindo; ter chegado; acabar de chegar a um lugar ou situação, ac. ou εἰς e ac., até alguém, dat. ou παρά e ac. 2 (coisa) ter vindo; chegar até alguém ou um local, dat. 3 (coisa) dizer respeito a; concernir a algo ou alguém, εἰς, ἐπί, πρός e ac. 4 com adv. εὖ ou καλῶς ἥκειν ir bem; sair-se bem 1 μάλα τηλόθεν ἥκω hom. venho de muito longe, ἰσθμὸν Κιμμερικὸν ἥξεις ésql. chegarás ao Istmo Cimérico, οὐ γὰρ ὀΐω ἥκειν εἰς Ἰθάκην hom. pois não acredito que me encontro em Ítaca, ἥκειν πρὸς πόλιν sóf. chegar perto da cidade, ἥκουσιν αὐτῷ ἄγγελοι xen. vêm até ele os mensageiros, αὐτὰ ταῦτα ἥκω παρὰ σέ plat. é exatamente por isso que venho a ti, εἰς τοσοῦτον ἀμαθίας ἥκω ὥστε plat. chego a tal ponto de ignorância que, εἰς τοσήνδ᾽ ὕβριν ἥκειν sóf. chegar a tal ponto de desmedida, οὕτω πόρρω σοφίας ἥκεις plat. chegaste a este ponto de sabedoria 2 ἥκει ἦμαρ ésql. chegou o dia, ἥξει πόλεμος tuc. uma guerra sobrevirá, ποῖ λόγοι ἥκει; eur. aonde levará este argumento? ἐμοὶ ἀγγελίη ἥκει παρὰ βασιλέος her. chegou-me uma mensagem do rei, δώμασιν ἡμετέροις φάτις ἥκει ar. à nossa casa chegou um rumor 3 ὅσα ἐπὶ τὴν πρεσβείαν ἧκε dem. tudo quanto à embaixada concernia, εἰς ἔμ᾽ ἥκει τῆς πόλεως τὰ πράγματα ar. a mim dizem respeito os negócios da cidade, τὰ εἰς πλοῦτον ἥκοντα plat. o que diz respeito à riqueza, τὰ πρὸς ἔπαινον ἥκοντα pol. o que concerne ao elogio 4 εὖ ἥκειν τοῦ βιοῦ her. ter êxito na vida, εὖ ἥκειν χρημάτων her. ser rico, καλῶς αὐτοῖς κατθάνειν ἧκον eur. ia bem para eles morrer.</p></section></article>\n<article id=\"entry-dgp-18493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλάθην</h1><div class=\"entry-meta\"><span>DGP · ordem 171 na letra η · nº geral 18493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. pas. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-18494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 172 na letra η · nº geral 18494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª pl. pres. dór. ἠλαίνοντι) jôn. 1 errar; vaguear 2 estar fora de si.</p></section></article>\n<article id=\"entry-dgp-18495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλάκατα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 173 na letra η · nº geral 18495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fio de lã na roca. 〈ἠλακάτη〉</p></section></article>\n<article id=\"entry-dgp-18496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλακάτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra η · nº geral 18496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caule de caniço 2 roca 3 fuso da roca 4 parte do mastro.</p></section></article>\n<article id=\"entry-dgp-18497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλάλαξα</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra η · nº geral 18497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλαλάζω.</p></section></article>\n<article id=\"entry-dgp-18498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra η · nº geral 18498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἅλλομαι.</p></section></article>\n<article id=\"entry-dgp-18499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλασα</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra η · nº geral 18499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-18500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλασκάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra η · nº geral 18500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἠλασκάζον) 1 errar; vagar 2 procurar evitar; evitar; fugir. 〈ἀλάομαι〉</p></section></article>\n<article id=\"entry-dgp-18501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλάσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra η · nº geral 18501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ir de um lado para outro; errar; vagar. 〈ἀλάομαι〉</p></section></article>\n<article id=\"entry-dgp-18502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλᾶτο</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra η · nº geral 18502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. de ἀλάομαι.</p></section></article>\n<article id=\"entry-dgp-18503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλατο</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra η · nº geral 18503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. de ἅλλομαι.</p></section></article>\n<article id=\"entry-dgp-18504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλγησα</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra η · nº geral 18504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλγέω.</p></section></article>\n<article id=\"entry-dgp-18505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλδανον</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra η · nº geral 18505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de ἀλδαίνω.</p></section></article>\n<article id=\"entry-dgp-18506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέ</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra η · nº geral 18506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép., voc. apoc. de ἠλεός.</p></section></article>\n<article id=\"entry-dgp-18507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλεάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra η · nº geral 18507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλέομαι.</p></section></article>\n<article id=\"entry-dgp-18508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλεγξα, ἠλέγχθην</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra η · nº geral 18508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐλέγχω.</p></section></article>\n<article id=\"entry-dgp-18509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέημαι, ἠλέησα</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra η · nº geral 18509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐλεέω.</p></section></article>\n<article id=\"entry-dgp-18510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλείφθην, ἤλειψα</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra η · nº geral 18510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀλείφω.</p></section></article>\n<article id=\"entry-dgp-18511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἠλέκτρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra η · nº geral 18511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Electra, filha de Agamenão.</p></section></article>\n<article id=\"entry-dgp-18512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέκτρινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra η · nº geral 18512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de âmbar 2 que tem cor de âmbar. 〈ἤλεκτρον〉</p></section></article>\n<article id=\"entry-dgp-18513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλεκτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra η · nº geral 18513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἤλεκτρος.</p></section></article>\n<article id=\"entry-dgp-18514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλεκτρος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra η · nº geral 18514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 âmbar 2 elétron, mistura de ouro e prata.</p></section></article>\n<article id=\"entry-dgp-18515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλεκτροφαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra η · nº geral 18515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que brilha como o âmbar. 〈ἤλεκτρον, φάος〉</p></section></article>\n<article id=\"entry-dgp-18516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέλιξα</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra η · nº geral 18516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐλελίζω1.</p></section></article>\n<article id=\"entry-dgp-18517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέματος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 195 na letra η · nº geral 18517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vão 2 tolo; insensato; transtornado ♦ ἠλέματα adv. 3 em vão; tolamente. 〈ἠλεός, μάτην〉</p></section></article>\n<article id=\"entry-dgp-18518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέξησα</h1><div class=\"entry-meta\"><span>DGP · ordem 196 na letra η · nº geral 18518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλέξω.</p></section></article>\n<article id=\"entry-dgp-18519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλεός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 197 na letra η · nº geral 18519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que torna louco; que perturba a razão 2 desarrazoado; louco; insensato.</p></section></article>\n<article id=\"entry-dgp-18520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλεσα, ἠλέσθην</h1><div class=\"entry-meta\"><span>DGP · ordem 198 na letra η · nº geral 18520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. at. e pas. de ἀλέω.</p></section></article>\n<article id=\"entry-dgp-18521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλήθην</h1><div class=\"entry-meta\"><span>DGP · ordem 199 na letra η · nº geral 18521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλάομαι.</p></section></article>\n<article id=\"entry-dgp-18522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤληθον</h1><div class=\"entry-meta\"><span>DGP · ordem 200 na letra η · nº geral 18522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἀλήθω.</p></section></article>\n<article id=\"entry-dgp-18523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠληλάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 201 na letra η · nº geral 18523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-18524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦλθον</h1><div class=\"entry-meta\"><span>DGP · ordem 202 na letra η · nº geral 18524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔρχομαι.</p></section></article>\n<article id=\"entry-dgp-18525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 203 na letra η · nº geral 18525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser membro do tribunal dos heliastas. 〈 Ἡλιαία〉</p></section></article>\n<article id=\"entry-dgp-18526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 204 na letra η · nº geral 18526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer cozer ao sol 2 expor ao sol (um condenado) ♦ méd. pas. 3 cozer ao sol 4 esquentar-se ao sol. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἡλιαία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 205 na letra η · nº geral 18527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Heliéia, em Atenas, nome da praça do tribunal dos heliastas e do próprio tribunal.</p></section></article>\n<article id=\"entry-dgp-18528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 206 na letra η · nº geral 18528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do sol; solar: ἔκλειψις ἡλ. d.l. eclipse solar ♦ ἡ ἡλιακή 2 ano solar. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 207 na letra η · nº geral 18529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 solar 2 consagrado ao sol. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἠλίας</h1><div class=\"entry-meta\"><span>DGP · ordem 208 na letra η · nº geral 18530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ἡλίας, ου (ὁ) Elias, profeta hebreu.</p></section></article>\n<article id=\"entry-dgp-18531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 209 na letra η · nº geral 18531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">heliasta, juiz. 〈ἡλιάζομαι〉</p></section></article>\n<article id=\"entry-dgp-18532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 210 na letra η · nº geral 18532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de heliasta: ἡλ. ὀβολός óbolo pago ao heliasta, ἡλ. ὅρκος juramento dos heliastas 2 semelhante a um heliasta. 〈ἡλιαστής〉</p></section></article>\n<article id=\"entry-dgp-18533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλίβατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 211 na letra η · nº geral 18533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 elevado; abrupto; escarpado 2 profundo 3 grande; enorme.</p></section></article>\n<article id=\"entry-dgp-18534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλιθα</h1><div class=\"entry-meta\"><span>DGP · ordem 212 na letra η · nº geral 18534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 desmesuradamente; imensamente 2 em vão; inutilmente.</p></section></article>\n<article id=\"entry-dgp-18535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλίθιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 213 na letra η · nº geral 18535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 insensato; tolo; estulto 2 mal regulado; desregrado; atrapalhado 3 inútil ♦ ἠλίθιον adv. 4 tolamente; loucamente.</p></section></article>\n<article id=\"entry-dgp-18536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλιθιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 214 na letra η · nº geral 18536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tolice; estupidez; irreflexão. 〈ἠλίθιος〉</p></section></article>\n<article id=\"entry-dgp-18537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλιθιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 215 na letra η · nº geral 18537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transtornar o espírito; aturdir. 〈ἠλίθιος〉</p></section></article>\n<article id=\"entry-dgp-18538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλιθίως</h1><div class=\"entry-meta\"><span>DGP · ordem 216 na letra η · nº geral 18538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. tolamente; estupidamente; com loucura.</p></section></article>\n<article id=\"entry-dgp-18539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλικία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 217 na letra η · nº geral 18539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ἡλικίη (ἡ) 1 idade; tempo de vida humana: παῖδές τε καὶ ἄνδρες καὶ πᾶσα ἡλικία plat. as crianças, os homens e os de qualquer idade, τοὺς ἐν ἡλικίᾳ στρατεύεσθαι dem. aqueles que estão na idade de combater 2 a força da idade; adolescência; maturidade; idade fecunda: ἐν τῇ ἡλικίᾳ tuc. na força da idade, εἰς ἡλικίαν ἐλθεῖν plat. chegar à maturidade, ἅπτεσθαι τῶν ἐν ἡλικίᾳ γυναικῶν plat. unir-se a mulheres que estão na idade fecunda 3 velhice; idade senil; marcas do tempo: προεληλυθὼς τῇ ἡλικίᾳ xen. avançado em idade 4 geração; período de tempo; época: ἡλικίην κατὰ Λάϊον her. no tempo de Laio, ἐπὶ τῆς νῦν ἡλικίας isócr. de nosso tempo, εἰς τὴν νῦν ζῶσαν ἡλικίαν dem. até a geração atual 5 da mesma idade; contemporâneo: οἱ ἐφ᾽ ἡλικίας, οἱ καθ᾽ ἡλικίαν plat. os contemporâneos 6 estatura; desenvolvimento; altura: ἄνδρας μεγάλους ὅσον ἡμισταδιαίους τὰς ἡλικίας luc. homens enormes da estatura de meio estádio. 〈ἧλιξ〉</p></section></article>\n<article id=\"entry-dgp-18540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλικιώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 218 na letra η · nº geral 18540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) contemporâneo de, gen. ou dat. 〈ἡλικία〉</p></section></article>\n<article id=\"entry-dgp-18541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλίκος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 219 na letra η · nº geral 18541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da mesma idade que; da mesma altura que; tão grande ou pequeno quanto: τοῖσιν ἡλίκοισι νῷν ar. para os homens da mesma idade que nós dois, τηλικοῦτον ἡλίκος οὐδείς πω βασιλεὺς γέγονε dem. tão poderoso como nenhum rei ainda foi 2 de que idade; quão grande, com inter. ind.: εἴδει ἡλίκος γέγονε plat. vais saber quão grande ele foi, ὁρᾷς μὲν ἡμᾶς ἡλίκοι προσήμεθα βωμοῖσι sóf. vês as idades que temos nós, que nos sentamos perto dos altares 3 em grau extraordinário: θαυμαστὸς ἡλίκος dem. espantosamente grande. 〈ἧλιξ〉</p></section></article>\n<article id=\"entry-dgp-18542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἧλιξ, ικος</h1><div class=\"entry-meta\"><span>DGP · ordem 220 na letra η · nº geral 18542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 da mesma idade; contemporâneo; companheiro ♦ ὁ, ἡ ἧλιξ 2 companheiro; colega.</p></section></article>\n<article id=\"entry-dgp-18543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιόβλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 221 na letra η · nº geral 18543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atingido pelos raios do sol. 〈ἥλιος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-18544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιοκαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 222 na letra η · nº geral 18544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">queimado pelo sol. 〈ἥλιος, καίω〉</p></section></article>\n<article id=\"entry-dgp-18545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιόκτυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 223 na letra η · nº geral 18545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atingido pelo sol. 〈ἥλιος, κτυπέω〉</p></section></article>\n<article id=\"entry-dgp-18546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλιος,</h1><div class=\"entry-meta\"><span>DGP · ordem 224 na letra η · nº geral 18546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ἠέλιος, dór. ἀέλιος e ἅλιος, ου (ὁ) 1 sol; calor do sol: φάος ἠελίοιο hom. a luz do sol, ἀφ᾽ ἡλίου ἀνιόντος μέχρι δυομένου ésqn. do nascer ao pôr do sol, οἵ τε ἥλιοι καὶ τὸ πνῖγος tuc. o calor do sol e a temperatura sufocante, ἥλιος πολύς luc. forte calor do sol 2 alegria; ardor; esplendor: ἥλιος ψυχῆς plut. sol da vida 3 dia: ἁλίῳ ἀμφ᾽ ἑνί pínd. durante um dia, ἡλίους δέκα luc. dez dias 4 levante; nascente: πρὸς ἠῶ τ᾽ ἠέλιον τε hom. para o lado da aurora e do nascente ♦ ὁ Ἥλιος 5 Hélio, Sol, deus: νὴ τὸ Ἥλιον men. sim, pelo Sol.</p></section></article>\n<article id=\"entry-dgp-18547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιοστερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 225 na letra η · nº geral 18547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que protege do sol. 〈ἥλιος, στερέω〉</p></section></article>\n<article id=\"entry-dgp-18548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιοτρόπιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 226 na letra η · nº geral 18548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 heliótropo, planta 2 quadrante solar; jornada ♦ ἡλ. μικρόν 3 girassol. 〈ἥλιος, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-18549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 227 na letra η · nº geral 18549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expor ao sol ♦ pas. 2 estar exposto ao sol 3 viver ao sol, ao ar livre. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλισα, ἡλίσθην, ἥλισμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 228 na letra η · nº geral 18550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἁλίζω2.</p></section></article>\n<article id=\"entry-dgp-18551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλίτησα</h1><div class=\"entry-meta\"><span>DGP · ordem 229 na letra η · nº geral 18551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀλιταίνω.</p></section></article>\n<article id=\"entry-dgp-18552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλιτόμηνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 230 na letra η · nº geral 18552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido antes do tempo; prematuro. 〈ἀλιταίνω, μήν〉</p></section></article>\n<article id=\"entry-dgp-18553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλιτον, ἀλιτεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 231 na letra η · nº geral 18553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ind. e inf. de ἀλιταίνω.</p></section></article>\n<article id=\"entry-dgp-18554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλίωσα</h1><div class=\"entry-meta\"><span>DGP · ordem 232 na letra η · nº geral 18554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἁλιόω e ἡλιόω.</p></section></article>\n<article id=\"entry-dgp-18555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 233 na letra η · nº geral 18555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) solar. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλιῶτις, ιδος,</h1><div class=\"entry-meta\"><span>DGP · ordem 234 na letra η · nº geral 18556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. -ιν (fem.) do sol; solar. 〈ἥλιος〉</p></section></article>\n<article id=\"entry-dgp-18557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλκησα</h1><div class=\"entry-meta\"><span>DGP · ordem 235 na letra η · nº geral 18557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἑλκέω.</p></section></article>\n<article id=\"entry-dgp-18558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλκωσα</h1><div class=\"entry-meta\"><span>DGP · ordem 236 na letra η · nº geral 18558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἑλκόω.</p></section></article>\n<article id=\"entry-dgp-18559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλλάγην, ἤλλαγμαι, ἤλλαξα, ἠλλάχθην</h1><div class=\"entry-meta\"><span>DGP · ordem 237 na letra η · nº geral 18559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀλλάσσω.</p></section></article>\n<article id=\"entry-dgp-18560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλλόμην</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra η · nº geral 18560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἅλλομαι.</p></section></article>\n<article id=\"entry-dgp-18561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλόησα, ἠλόημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra η · nº geral 18561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀλοάω.</p></section></article>\n<article id=\"entry-dgp-18562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλόμην</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra η · nº geral 18562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de ἅλλομαι.</p></section></article>\n<article id=\"entry-dgp-18563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἧλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra η · nº geral 18563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prego 2 cravo de ornamento (em cetro; espada) 3 cavilha de madeira 4 excrescência em forma de prego (calo; verruga) 5 espécie de cogumelo parasita em algumas árvores.</p></section></article>\n<article id=\"entry-dgp-18564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra η · nº geral 18564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἠλιθιότης.</p></section></article>\n<article id=\"entry-dgp-18565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλουν, εις</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra η · nº geral 18565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἀλέω.</p></section></article>\n<article id=\"entry-dgp-18566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλπιζον, ἤλπισα</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra η · nº geral 18566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐλπίζω.</p></section></article>\n<article id=\"entry-dgp-18567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλπόμην</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra η · nº geral 18567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἔλπω.</p></section></article>\n<article id=\"entry-dgp-18568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλύγη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra η · nº geral 18568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">obscuridade; trevas.</p></section></article>\n<article id=\"entry-dgp-18569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλυθον</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra η · nº geral 18569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 poét. de ἔρχομαι.</p></section></article>\n<article id=\"entry-dgp-18570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλυξα</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra η · nº geral 18570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλύσκω.</p></section></article>\n<article id=\"entry-dgp-18571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤλυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra η · nº geral 18571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">marcha; passo; modo de andar.</p></section></article>\n<article id=\"entry-dgp-18572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦλφον</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra η · nº geral 18572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἀλφάνω.</p></section></article>\n<article id=\"entry-dgp-18573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra η · nº geral 18573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. impf. de ἀλάομαι.</p></section></article>\n<article id=\"entry-dgp-18574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλω</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra η · nº geral 18574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing de ἅλλομαι ou 3ª sing. aor.2 de ἁλίσκομαι.</p></section></article>\n<article id=\"entry-dgp-18575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλωκα, ἡλώκειν</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra η · nº geral 18575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. e m.-q.-perf. jôn. de ἁλίσκομαι.</p></section></article>\n<article id=\"entry-dgp-18576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλώμην</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra η · nº geral 18576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἀλάομαι.</p></section></article>\n<article id=\"entry-dgp-18577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλων</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra η · nº geral 18577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 jôn. de ἀλίσκομαι.</p></section></article>\n<article id=\"entry-dgp-18578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἧμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra η · nº geral 18578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">projétil; dardo; lança.</p></section></article>\n<article id=\"entry-dgp-18579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠμαθόεις, όεις</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra η · nº geral 18579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e όεσσα, όεν jôn. arenoso. 〈ἄμαθος〉</p></section></article>\n<article id=\"entry-dgp-18580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἧμαι, ἧσαι, ἧσται</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra η · nº geral 18580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. ἧνται ép. εἵαται, (só pres. e impf. ἧμην, inf. ἧσθαι, part. ἥμενος ) 1 estar sentado: βιαίως σέλμα σεμνὸς ἡμένων ésql. sob coação sentados junto ao majestoso trono 2 achar-se pousado; estar estabelecido; estar colocado em, ἐν e dat., rar. só dat. ou só ac.; sobre, ἐπί e gen. ou dat.; junto a, παρά e dat.: οἱ ἐν ἀρχαῖς ἥμενοι eur. aqueles que estão entre os que exercem funções no governo, ἧμαι ὀδυρόμενος hom. fico aqui gemendo 3 estar acampado: ἧμαι πρόσθε τειχέων eur. estar acampado diante das muralhas 4 (edifício) situar-se: τῇ ἱρὸν ἧσται her. lá onde se situa o templo 5 ficar calmo; ficar em repouso; ficar inativo: κατ᾽ οἴκους ἐκτὸς ἧσθαι πόνων eur. ficar em casa longe das fadigas. ᾕμαξα aor. de αἱμάσσω.</p></section></article>\n<article id=\"entry-dgp-18581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦμαρ, ἤματος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra η · nº geral 18581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 dia (op. a noite): νύκτες τε καὶ ἤματα hom. as noites e os dias; μέσον ἦμαρ hom. o meio dia 2 dia (duração): ἤματα πάντα hom. todos os dias; sempre, ἐπ᾽ ἤματι em um dia; por dia; de dia, κατ᾽ ἦμαρ a cada dia, παρ᾽ ἦμαρ em um dia ou dia por dia, παρ᾽ ἦμαρ ἡμέρα sóf. dia após dia, τὸ κατ᾽ ἦμαρ o de cada dia, ἦμαρ ἀναγκαῖον hom. dia marcado pelo destino, ἦμαρ λευκόν ésql. dia brilhante; dia de felicidade, νόστιμον ἦμαρ hom. dia do regresso 3 dia; tempo; estação: ἤματι χειμερίῳ hom. em um dia de inverno; na estação do inverno 4 dia; tempo: ἤματι τῷ ὅτε no tempo em que ♦ ἦμαρ adv. 5 durante o dia.</p></section></article>\n<article id=\"entry-dgp-18582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμάρτηκα, ἡμαρτήθην, ἡμάρτημαι, ἥμαρτον</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra η · nº geral 18582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἁμαρ­τάνω.</p></section></article>\n<article id=\"entry-dgp-18583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμᾶς</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra η · nº geral 18583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át., jôn. ép. ἧμας, contr. de ἡμέας ac. de ἡμεῖς cf. ἐγώ.</p></section></article>\n<article id=\"entry-dgp-18584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠμάτιος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra η · nº geral 18584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de dia; diurno 2 cotidiano. 〈ἦμαρ〉</p></section></article>\n<article id=\"entry-dgp-18585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ᾑματωμένος</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra η · nº geral 18585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. pas. de αἱματόω.</p></section></article>\n<article id=\"entry-dgp-18586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤμβλωσα</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra η · nº geral 18586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀμβλόω.</p></section></article>\n<article id=\"entry-dgp-18587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤμβροτον</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra η · nº geral 18587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 ép. de ἁμαρτάνω.</p></section></article>\n<article id=\"entry-dgp-18588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠμέας</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra η · nº geral 18588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἡμᾶς.</p></section></article>\n<article id=\"entry-dgp-18589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤμειμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra η · nº geral 18589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἀμείβω.</p></section></article>\n<article id=\"entry-dgp-18590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμεῖς</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra η · nº geral 18590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pron. pes., nom. pl. nós, cf. ἐγώ.</p></section></article>\n";
